amiliar language."},{"query":"read then","rationale":"Explicit bounded usage fallback for validated A1 target collocation: read then"},{"query":"read then help","rationale":"Explicit bounded usage fallback for validated A1 target collocation: read then help"}]},"pedagogyVersion":2},"pilot":false,"audioRequired":true,"humanEnglishAuditRequired":true,"dialogueRuntime":"guided_exchange","qualityStage":"model_reviewed_for_testing","qualityV2Remediated":true,"qualityV2RemediationVersion":1,"qualityV2Polished":true,"qualityV2PolishVersion":2}')
